1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An interactive color-changing circle with keyboard and touch controls">
7	  <meta name="theme-color" content="#5f6fd1" media="(prefers-color-scheme: dark)">
8	  <meta name="theme-color" content="#a8b5e8" media="(prefers-color-scheme: light)">
9	  <title>Circle Display</title>
10	  <style>
11	    :root {
12	      --color-white: #ffffff;
13	      --color-gold: #ffd700;
14	      --color-pink: #ff6b9d;
15	      --color-teal: #4ecdc4;
16	      --color-mint: #95e1d3;
17	      --shadow-color: rgba(0, 0, 0, 0.3);
18	      --transition-normal: 0.3s ease;
19	      --transition-slow: 0.6s ease-out;
20	      --pulse-duration: 2.5s;
21	      --color-mode-1-rgb: 255, 107, 157;
22	      --color-mode-2-rgb: 78, 205, 196;
23	      --color-mode-3-rgb: 149, 225, 211;
24	    }
25	
26	    * {
27	      margin: 0;
28	      padding: 0;
29	      box-sizing: border-box;
30	    }
31	    html, body {
32	      width: 100%;
33	      height: 100%;
34	      overflow: hidden;
35	    }
36	    body {
37	      display: flex;
38	      flex-direction: column;
39	      justify-content: center;
40	      align-items: center;
41	      gap: 20px;
42	      background: linear-gradient(135deg, #5f6fd1 0%, #6b3fa0 100%);
43	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
44	      color: var(--color-white);
45	      font-size: 14px;
46	      padding: 20px;
47	      min-height: 100vh;
48	    }
49	    .circle-container {
50	      cursor: pointer;
51	      border: none;
52	      background: none;
53	      padding: 0;
54	      position: relative;
55	      contain: layout style paint;
56	    }
57	    .circle-container:hover {
58	      transform: scale(1.05);
59	    }
60	    .circle-container:focus {
61	      outline: none;
62	    }
63	    .circle-container:focus-visible {
64	      transform: scale(1.08);
65	      outline: 3px solid rgba(255, 255, 255, 0.7);
66	      outline-offset: 12px;
67	      border-radius: 50%;
68	    }
69	    svg {
70	      width: min(400px, 80vw);
71	      height: min(400px, 80vw);
72	      display: block;
73	      animation: fadeIn var(--transition-slow);
74	    }
75	    circle {
76	      fill: var(--color-white);
77	      stroke: rgba(255, 255, 255, 0.25);
78	      stroke-width: 1.5;
79	      animation: pulse var(--pulse-duration) ease-in-out infinite;
80	      filter: drop-shadow(0 20px 40px var(--shadow-color));
81	      transition: fill 0.3s ease, r 0.3s ease, stroke 0.3s ease, filter 0.3s ease;
82	    }
83	    .circle-container:is(:hover, :focus-visible) circle {
84	      fill: #e8f4f8;
85	      r: 205;
86	      stroke: rgba(255, 255, 255, 0.4);
87	    }
88	    .circle-container.active circle {
89	      fill: var(--color-gold);
90	      stroke: rgba(255, 215, 0, 0.3);
91	      animation: pulse-active 0.6s ease-in-out;
92	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
93	      r: 200;
94	    }
95	
96	    .circle-container.color-mode-1 { --mode-color: var(--color-pink); --mode-rgb: var(--color-mode-1-rgb); }
97	    .circle-container.color-mode-2 { --mode-color: var(--color-teal); --mode-rgb: var(--color-mode-2-rgb); }
98	    .circle-container.color-mode-3 { --mode-color: var(--color-mint); --mode-rgb: var(--color-mode-3-rgb); }
99	
100	    [class*="color-mode-"] circle {
101	      fill: var(--mode-color);
102	      stroke: rgba(var(--mode-rgb), 0.3);
103	      filter: drop-shadow(0 20px 40px rgba(var(--mode-rgb), 0.3));
104	    }
105	    [class*="color-mode-"]:is(:hover, :focus-visible) circle {
106	      stroke: rgba(var(--mode-rgb), 0.5);
107	    }
108	    [class*="color-mode-"].active circle {
109	      filter: drop-shadow(0 20px 40px rgba(var(--mode-rgb), 0.5));
110	    }
111	
112	    .hint {
113	      font-size: 12px;
114	      opacity: 0.9;
115	      transition: opacity var(--transition-normal);
116	      letter-spacing: 0.5px;
117	      max-width: 90%;
118	      line-height: 1.6;
119	      margin-top: 12px;
120	      position: relative;
121	      text-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
122	    }
123	
124	    .mode-indicator {
125	      font-size: 10px;
126	      opacity: 0;
127	      margin-top: 8px;
128	      letter-spacing: 1px;
129	      text-transform: uppercase;
130	      transition: opacity var(--transition-normal);
131	      height: 16px;
132	    }
133	    .mode-indicator.visible {
134	      opacity: 0.9;
135	    }
136	
137	    .controls {
138	      display: flex;
139	      gap: 12px;
140	      margin-top: 10px;
141	      flex-wrap: wrap;
142	      justify-content: center;
143	      width: 100%;
144	    }
145	
146	    .control-btn {
147	      padding: 10px 20px;
148	      font-size: 12px;
149	      font-weight: 600;
150	      letter-spacing: 0.8px;
151	      text-transform: uppercase;
152	      background: rgba(255, 255, 255, 0.18);
153	      color: var(--color-white);
154	      border: 1.5px solid rgba(255, 255, 255, 0.35);
155	      border-radius: 24px;
156	      cursor: pointer;
157	      transition: background-color var(--transition-normal), border-color var(--transition-normal), transform var(--transition-normal), box-shadow var(--transition-normal);
158	      backdrop-filter: blur(4px);
159	      outline: none;
160	    }
161	
162	    .control-btn:hover {
163	      background: rgba(255, 255, 255, 0.28);
164	      border-color: rgba(255, 255, 255, 0.6);
165	      transform: translateY(-3px);
166	      box-shadow: 0 10px 20px rgba(0, 0, 0, 0.25);
167	    }
168	
169	    .control-btn:active {
170	      transform: translateY(0) scale(0.96);
171	      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
172	    }
173	
174	    .control-btn:focus-visible {
175	      outline: 2px solid rgba(255, 255, 255, 0.7);
176	      outline-offset: 4px;
177	    }
178	    .control-btn:disabled {
179	      opacity: 0.5;
180	      cursor: not-allowed;
181	    }
182	    @keyframes pulse {
183	      0%, 100% { r: 200; opacity: 0.95; }
184	      50% { r: 203; opacity: 1; }
185	    }
186	    @keyframes pulse-active {
187	      0% { r: 200; }
188	      50% { r: 210; }
189	      100% { r: 200; }
190	    }
191	    @keyframes fadeIn {
192	      from { opacity: 0; transform: scale(0.9); }
193	      to { opacity: 1; transform: scale(1); }
194	    }
195	    @keyframes colorShift {
196	      0% { filter: saturate(1) brightness(1); }
197	      50% { filter: saturate(1.3) brightness(1.1); }
198	      100% { filter: saturate(1) brightness(1); }
199	    }
200	    .color-shifting circle {
201	      animation: colorShift 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
202	      transform-origin: center;
203	    }
204	    .keyboard-hint {
205	      font-size: 10px;
206	      opacity: 0.6;
207	      margin-top: 6px;
208	      letter-spacing: 0.3px;
209	      transition: opacity var(--transition-normal);
210	    }
211	    .keyboard-hint kbd {
212	      background: rgba(255, 255, 255, 0.15);
213	      border: 1px solid rgba(255, 255, 255, 0.25);
214	      border-radius: 3px;
215	      padding: 2px 6px;
216	      font-family: 'Monaco', 'Courier New', monospace;
217	      font-size: 9px;
218	      font-weight: 500;
219	      display: inline-block;
220	      margin: 0 2px;
221	    }
222	    @media (pointer: coarse) {
223	      .keyboard-hint {
224	        display: none;
225	      }
226	    }
227	    main {
228	      display: flex;
229	      flex-direction: column;
230	      align-items: center;
231	      justify-content: center;
232	      gap: 12px;
233	      text-align: center;
234	      width: 100%;
235	      flex: 1;
236	    }
237	
238	    @media (max-width: 600px) {
239	      svg {
240	        width: min(320px, 75vw);
241	        height: min(320px, 75vw);
242	      }
243	      .hint {
244	        font-size: 11px;
245	        margin-top: 10px;
246	      }
247	      .control-btn {
248	        padding: 12px 20px;
249	        font-size: 11px;
250	        min-height: 44px;
251	        display: flex;
252	        align-items: center;
253	        justify-content: center;
254	      }
255	    }
256	    @media (max-width: 480px) {
257	      body {
258	        gap: 12px;
259	        padding: 16px;
260	      }
261	      .mode-indicator {
262	        font-size: 9px;
263	      }
264	    }
265	    @media (max-width: 360px) {
266	      body {
267	        gap: 8px;
268	        padding: 12px;
269	      }
270	      svg {
271	        width: min(280px, 70vw);
272	        height: min(280px, 70vw);
273	      }
274	      .controls {
275	        flex-wrap: wrap;
276	      }
277	      .mode-indicator {
278	        font-size: 10px;
279	      }
280	      .keyboard-hint {
281	        font-size: 9px;
282	      }
283	      .keyboard-hint kbd {
284	        padding: 3px 6px;
285	        font-size: 8px;
286	      }
287	    }
288	    @media (prefers-reduced-motion: reduce) {
289	      * {
290	        animation: none !important;
291	        transition: none !important;
292	      }
293	    }
294	    @supports (backdrop-filter: blur(0)) {
295	      .control-btn {
296	        background: rgba(255, 255, 255, 0.1);
297	      }
298	    }
299	    @supports not (backdrop-filter: blur(0)) {
300	      .control-btn {
301	        background: rgba(0, 0, 0, 0.3);
302	      }
303	    }
304	    @media (prefers-color-scheme: light) {
305	      body {
306	        background: linear-gradient(135deg, #a8b5e8 0%, #c99fe6 100%);
307	      }
308	      circle {
309	        fill: #f5f5f5;
310	        stroke: rgba(0, 0, 0, 0.15);
311	      }
312	      .circle-container:is(:hover, :focus-visible) circle {
313	        fill: #e0e0e0;
314	        stroke: rgba(0, 0, 0, 0.25);
315	      }
316	      .control-btn {
317	        background: rgba(255, 255, 255, 0.25);
318	        border-color: rgba(255, 255, 255, 0.45);
319	      }
320	      .control-btn:hover {
321	        background: rgba(255, 255, 255, 0.35);
322	      }
323	    }
324	  </style>
325	</head>
326	<body>
327	  <main>
328	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to toggle" aria-pressed="false">
329	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
330	        <circle cx="200" cy="200" r="200"/>
331	      </svg>
332	    </button>
333	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true" aria-label="Current color mode"></div>
334	    <div class="controls" role="group" aria-label="Circle controls">
335	      <button class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
336	      <button class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
337	    </div>
338	  </main>
339	  <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click to activate • Double-click to change color</div>
340	  <div class="keyboard-hint" aria-label="Keyboard shortcuts: Space or Enter to toggle, C to cycle color, R to reset">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
341	
342	  <script>
343	    const CONFIG = {
344	      storageKey: 'circle-state',
345	      tapDelay: 300,
346	      colorShiftDuration: 500,
347	      colorModes: [
348	        { class: 'default', name: 'Default White' },
349	        { class: 'color-mode-1', name: 'Pink' },
350	        { class: 'color-mode-2', name: 'Teal' },
351	        { class: 'color-mode-3', name: 'Mint' }
352	      ],
353	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
354	      pulseInterval: 2500
355	    };
356	
357	    const el = {
358	      circle: document.getElementById('decorative-circle'),
359	      hint: document.getElementById('hint-text'),
360	      modeIndicator: document.getElementById('mode-indicator'),
361	      cycleBtn: document.getElementById('cycle-btn'),
362	      resetBtn: document.getElementById('reset-btn')
363	    };
364	
365	    let state = { active: false, colorMode: 0 };
366	    let lastTapTime = 0;
367	    let tapTimeout = null;
368	    let animatingColorShift = false;
369	
370	    const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
371	    const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
372	
373	    const storage = {
374	      save() {
375	        try {
376	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
377	        } catch {
378	          // Silently fail if localStorage is unavailable or quota exceeded
379	        }
380	      },
381	      load() {
382	        try {
383	          const saved = localStorage.getItem(CONFIG.storageKey);
384	          if (saved) {
385	            const parsed = JSON.parse(saved);
386	            if (parsed && typeof parsed === 'object') {
387	              state = { ...state, ...parsed };
388	            }
389	          }
390	        } catch {
391	          // Silently fail if parsing fails
392	        }
393	      }
394	    };
395	
396	    const updateClasses = () => {
397	      const colorClasses = CONFIG.colorModes.map(m => m.class);
398	      el.circle.classList.remove('active', ...colorClasses);
399	      el.circle.setAttribute('aria-pressed', state.active);
400	      if (state.active) el.circle.classList.add('active');
401	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
402	    };
403	
404	    const updateUI = () => {
405	      const mainText = state.active ? 'Active!' : 'Click to activate';
406	      let hintParts = [mainText];
407	
408	      if (CONFIG.isTouch) {
409	        hintParts.push(state.active ? 'Tap to change color' : 'Tap twice to change color');
410	      } else {
411	        hintParts.push('Double-click to change color');
412	      }
413	
414	      el.hint.textContent = hintParts.join(' • ');
415	
416	      const showMode = state.active && state.colorMode > 0;
417	      el.modeIndicator.classList.toggle('visible', showMode);
418	      if (showMode) {
419	        const modeName = getColorModeName(state.colorMode);
420	        el.modeIndicator.textContent = modeName;
421	      }
422	    };
423	
424	    const applyState = () => {
425	      updateClasses();
426	      updateUI();
427	    };
428	
429	    const toggleActive = () => {
430	      state.active = !state.active;
431	      applyState();
432	      storage.save();
433	    };
434	
435	    const cycleColor = () => {
436	      if (animatingColorShift) return;
437	      animatingColorShift = true;
438	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
439	      state.active = true;
440	      el.circle.classList.add('color-shifting');
441	      setTimeout(() => {
442	        el.circle.classList.remove('color-shifting');
443	        animatingColorShift = false;
444	      }, CONFIG.colorShiftDuration);
445	      applyState();
446	      storage.save();
447	    };
448	
449	    const resetState = () => {
450	      state = { active: false, colorMode: 0 };
451	      applyState();
452	      storage.save();
453	    };
454	
455	    const handleDblClick = (e) => {
456	      e.preventDefault();
457	      cycleColor();
458	    };
459	
460	    const handleTouchEnd = (e) => {
461	      const now = Date.now();
462	      if (now - lastTapTime < CONFIG.tapDelay && lastTapTime > 0) {
463	        cycleColor();
464	        lastTapTime = 0;
465	        clearTimeout(tapTimeout);
466	      } else {
467	        lastTapTime = now;
468	        clearTimeout(tapTimeout);
469	        tapTimeout = setTimeout(() => { lastTapTime = 0; }, CONFIG.tapDelay);
470	      }
471	    };
472	
473	    const keyHandlers = {
474	      ' ': toggleActive,
475	      'enter': toggleActive,
476	      'c': cycleColor,
477	      'r': resetState
478	    };
479	
480	    const handleKeyDown = (e) => {
481	      const handler = keyHandlers[e.key.toLowerCase()];
482	      if (handler) {
483	        e.preventDefault();
484	        handler();
485	      }
486	    };
487	
488	    const initListeners = () => {
489	      el.circle.addEventListener('click', toggleActive);
490	      el.circle.addEventListener('dblclick', handleDblClick);
491	      el.circle.addEventListener('touchend', handleTouchEnd);
492	      el.circle.addEventListener('blur', () => {
493	        lastTapTime = 0;
494	        clearTimeout(tapTimeout);
495	      });
496	      document.addEventListener('keydown', handleKeyDown);
497	      el.cycleBtn.addEventListener('click', cycleColor);
498	      el.resetBtn.addEventListener('click', resetState);
499	    };
500	
501	    const initApp = () => {
502	      storage.load();
503	      applyState();
504	      initListeners();
505	      requestAnimationFrame(() => el.circle.focus());
506	    };
507	
508	    if (document.readyState === 'loading') {
509	      document.addEventListener('DOMContentLoaded', initApp);
510	    } else {
511	      initApp();
512	    }
513	  </script>
514	</body>
515	</html>
